import {modelBadge} from './model-identity.js?v=20261031-player6';
import {previewableCheckupSVG} from './checkup-data.js?v=20261031-player6';
import {checkupSVG} from './checkup-view.js?v=20261031-player6';
import {weightedGrade,weightedSummary,formatPoints,taskName} from './weighted-score.js?v=20261031-player6';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function extractDrawing(output){const text=String(output||''),matches=text.match(/<svg\b[\s\S]*?<\/svg>/gi);const svg=matches?.length===1?matches[0]:text;return {svg,fenced:svg.trim()!==text.trim()};}
export function validateCompletedSuite(suite,data,old,bank){
  const fail=()=>{throw Error('八项成绩与来源记录不匹配');},ids=['purpose','reasoning','edit','memory','honesty','visual','receipt','zebra'],weights=[10,10,10,10,15,10,20,15];
  if(suite?.schemaVersion!=='daily-weighted-v3'||suite.suiteId!=='zhufeng-daily-eight-v3'||suite.scoreVersion!=='weighted-100-v3'||suite.maxScore!==100||suite.passingScore!==80||suite.excellentScore!==90||suite.tasks?.length!==8||suite.models?.length!==data.models.length||suite.origin!=='assistant-reviewed-api-completions'||!Number.isFinite(Date.parse(suite.updatedAt)))fail();
  if(suite.sourceSuiteId!==data.suiteId||suite.condition!=='per-task-recorded')fail();
  suite.tasks.forEach((t,i)=>{if(t.id!==ids[i]||t.weight!==weights[i]||!Array.isArray(t.prompts)||!t.prompts.length||t.prompts.some(p=>typeof p!=='string'||!p.trim()))fail();if(i<6&&JSON.stringify(t.prompts)!==JSON.stringify(bank.tasks[i].prompts))fail();});
  if(suite.tasks[6].prompts[0]!=='请告诉我这个账单，辣椒炒肉有几份？'||suite.tasks[6].image!=='assets/receipt-chilli-pork.png'||suite.tasks[7].criteria?.length!==4||suite.tasks[7].criteria.some((c,i)=>c.max!==[5,4,3,3][i]))fail();
  let requests=0,successes=0;
  suite.models.forEach((row,i)=>{if(row.modelId!==data.models[i].id||row.sourceDigest!==data.models[i].sourceDigest||row.items?.length!==8)fail();row.items.forEach((x,j)=>{
    if(x.taskId!==ids[j]||x.score!==null&&(typeof x.score!=='number'||!Number.isFinite(x.score)||x.score<0||x.score>2)||typeof x.reason!=='string')fail();
    if(j<6){if(x.score!==old.models[i].items[j].score||x.reason!==old.models[i].items[j].reason)fail();return;}
    const m=x.measurement;if(!m){if(x.score!==null)fail();return;}requests++;successes+=m.status==='success';
    if(!['success','error','timeout'].includes(m.status)||m.apiModel!==data.models[i].apiModel||m.provider!=='CommandCode'||x.reviewer!=='assistant-first-pass'||!/^[a-f0-9]{64}$/.test(m.sourceDigest)||typeof m.output!=='string'||m.output.length>150000||!Number.isFinite(Date.parse(m.checkedAt)))fail();
    if(j===6){if(![null,0,2].includes(x.score)||m.imageSha256!=='73a513249777e5c4ea4d88545e9c7c0b83344b9284f5b0b29c0f0b5690ccee11'||m.status!=='success'&&x.score!==null)fail();}
    if(j===7&&x.score!==null){const picture=extractDrawing(m.output),canPreview=m.status==='success'&&previewableCheckupSVG(picture.svg);if(!canPreview){if(x.score!==0||x.criteriaScores?.length)fail();}else{if(x.criteriaScores?.length!==4)fail();const maxima=[5,4,3,3];let total=0;x.criteriaScores.forEach((c,k)=>{if(!Number.isInteger(c.awarded)||c.awarded<0||c.awarded>maxima[k]||typeof c.reason!=='string')fail();total+=c.awarded;});if(Math.abs(total-x.score*15/2)>1e-7)fail();}}
  });});
  if(suite.newRequests!==requests||suite.newSuccesses!==successes)fail();return suite;
}
export function completedItem(suite,row,id){return row.items.find(x=>x.taskId===id);}
export function completionBody(suite,row,id){
  const i=suite.tasks.findIndex(t=>t.id===id),item=row.items[i],m=item.measurement;if(!m||m.status==='not_run')return `<p class="checkup-warning">${e(item.reason||'尚未发送本项测试。')}</p>`;
  const result=`<p class="evidence-meta">${e(item.reason)}</p>`;
  let graphic='';if(id==='zebra'){const pic=extractDrawing(m.output);graphic=m.status==='success'&&previewableCheckupSVG(pic.svg)?`${pic.fenced?'<p class="checkup-warning">已提取原回答中的图形预览，格式问题计入评分。</p>':''}${checkupSVG(pic.svg,"AI 生成绘图：查看条纹、奔跑姿态和草原环境。")}`:'<p class="checkup-warning">本次没有完整、安全可预览的图形。失败原文与状态保留。</p>';}
  const scores=item.criteriaScores?.length?`<ul class="drawing-criteria">${item.criteriaScores.map((c,k)=>`<li>${e(suite.tasks[i].criteria[k].label)}：${c.awarded} / ${suite.tasks[i].criteria[k].max} · ${e(c.reason)}</li>`).join('')}</ul>`:'';
  return result+graphic+scores+`${id==='receipt'?`<pre class="checkup-answer">${e(m.output||'没有返回正文。')}</pre>`:`<details><summary>查看原始SVG回答</summary><pre class="checkup-answer">${e(m.output||'没有返回正文。')}</pre></details>`}<details class="pub-conditions"><summary>本次测试条件与来源</summary><p>${e(m.condition)}<br>${e(m.apiModel)} · ${e(m.provider)}<br>${e(m.checkedAt)}<br>状态：${e(m.status)} ${e(m.error||'')}<br>原记录摘要：${e(m.sourceDigest)}</p></details><p class="evidence-meta">${item.reviewer==='site-owner'?'站长确认':'助手初评'}</p>`;
}
export function completionCard(suite,row,m,id){const i=suite.tasks.findIndex(t=>t.id===id);return `<section class="panel"><div class="panel-head"><h2>${i+1}. ${e(taskName(suite.tasks[i]))} · ${suite.tasks[i].weight}分</h2><span class="checkup-status">${weightedGrade(suite,row,i)}分</span></div><div class="panel-body"><p>${e(id==='zebra'?suite.tasks[i].title:suite.tasks[i].prompts[0])}</p>${id==='zebra'?`<details><summary>查看发给模型的完整提问</summary><pre class="checkup-answer">${e(suite.tasks[i].prompts[0])}</pre></details>`:''}${id==='receipt'?'<a href="#checkup/receipt">查看测试原图 ↗</a>':''}${completionBody(suite,row,id)}</div></section>`;}
export function completionComparison(suite,data,models,id){const i=suite.tasks.findIndex(t=>t.id===id);return `<section class="panel"><div class="panel-head"><h2>${e(taskName(suite.tasks[i]))} · ${suite.tasks[i].weight}分</h2></div><div class="panel-body"><p>${e(suite.tasks[i].title)}</p><div class="checkup-pair">${models.map(m=>{const row=suite.models.find(r=>r.modelId===m.id);return `<div><h3 class="model-heading">${modelBadge(m.id)}<span>${e(m.name)}</span>${m.selectedEffort?' · '+e(m.selectedEffort):''} · ${weightedGrade(suite,row,i)}分</h3>${completionBody(suite,row,id)}</div>`;}).join('')}</div></div></section>`;}
export function zebraPage(suite,data){return `<div class="page-head"><div><div class="eyebrow">逐风 / ZEBRA DRAWING</div><h1>草原上，奔跑的斑马。</h1><p class="subtitle">非洲稀树草原，黑白条纹，奔跑姿态。八项百分制中的15分。</p></div><a class="button-link" href="#checkup">← 返回测试集</a></div><section class="panel"><div class="panel-body"><p>画一只在非洲稀树草原上奔跑的斑马。看条纹、奔跑姿态和草原环境。</p><details><summary>查看发给模型的完整提问</summary><pre class="checkup-answer">${e(suite.tasks[7].prompts[0])}</pre></details><p class="evidence-meta">绘图方式：SVG 代码绘图 · 助手初评。</p></div></section>${data.models.map(m=>{const row=suite.models.find(r=>r.modelId===m.id);return `<article class="panel"><div class="panel-head"><h2><a class="model-nameplate" href="#checkup/model/${e(m.id)}">${modelBadge(m.id)}<span>${e(m.name)}</span></a>${m.selectedEffort?' · '+e(m.selectedEffort):''}</h2><span>${weightedGrade(suite,row,7)}分</span></div><div class="panel-body">${completionBody(suite,row,'zebra')}</div></article>`;}).join('')}`;}
